            return true;
        }
        return false;
    }

    ///
    /// @inheritdoc IFijaStrategy
    ///
    function needEmergencyMode() public view virtual override returns (bool) {
        FijaStrategyStorage storage $ = _getFijaStrategyStorage();
        if ($._isEmergencyMode) {
            return false;
        }
        HealthOracleStorage storage h = _getHealthOracleStorage();
        if (!h.healthOracle.validateNeedEmeMode()) {
            return true;
        }

        return PERIPHERY.needEmergencyMode();
    }

    ///
    /// NOTE: rebalance is perfomed based on timespan and total asset thresholds
    /// @inheritdoc IFijaStrategy
    ///
    function needRebalance() external view virtual override returns (bool) {
        if (totalSupply() == 0) {
            return false;
        }
        uint256 totalAsset = totalAssets();
        BaseConstantsStorage storage $ = _getBaseConstantsStorage();
        FijaStrategyStorage storage $$ = _getFijaStrategyStorage();

        if (
            $$._lastRebalanceTime + $.REBALANCE_TIME_UPPER < block.timestamp &&
            $.REBALANCE_THR1 <= totalAsset &&
            $.REBALANCE_THR2 > totalAsset
        ) {
            return true;
        }
        if (
            $$._lastRebalanceTime + $.REBALANCE_TIME_LOWER < block.timestamp &&
            $.REBALANCE_THR2 <= totalAsset
        ) {
            return true;
        }
        return false;
    }

    ///
    /// NOTE: uses periphery contract to query status()
    /// @inheritdoc IFijaStrategy
    ///
    function status() external view virtual override returns (string memory) {
        BasePoolMetaStorage storage $ = _getBasePoolMetaStorage();
        BasePoolStorage storage $$ = _getBasePoolStorage();
        BaseConstantsStorage storage c = _getBaseConstantsStorage();

        return CurveConvexLib.status($, $$, c, DEPOSIT_CCY, POOL_NUM);
    }

    ///
    /// @inheritdoc FijaStrategy
    ///
    function deposit(
        uint256 assets,
        address receiver
    ) public payable virtual override(FijaStrategy) returns (uint256) {
        HealthOracleStorage storage h = _getHealthOracleStorage();
        h.healthOracle.validateDepositWithdraw(true, false);

        return super.deposit(assets, receiver);
    }

    ///
    /// @inheritdoc FijaStrategy
    ///
    function redeem(
        uint256 tokens,
        address receiver,
        address owner
    ) public payable virtual override(FijaStrategy) returns (uint256) {
        FijaStrategyStorage storage $ = _getFijaStrategyStorage();
        HealthOracleStorage storage h = _getHealthOracleStorage();

        h.healthOracle.validateDepositWithdraw(false, $._isEmergencyMode);

        return super.redeem(tokens, receiver, owner);
    }

    ///
    /// @inheritdoc FijaStrategy
    ///
    function withdraw(
        uint256 assets,
        address receiver,
        address owner
    ) public payable virtual override(FijaStrategy) returns (uint256) {
        FijaStrategyStorage storage $ = _getFijaStrategyStorage();
        HealthOracleStorage storage h = _getHealthOracleStorage();

        h.healthOracle.validateDepositWithdraw(false, $._isEmergencyMode);

        return super.withdraw(assets, receiver, owner);
    }

    ///
    /// @inheritdoc FijaStrategy
    ///
    function rebalance() public payable virtual override {
        HealthOracleStorage storage h = _getHealthOracleStorage();
        h.healthOracle.validateRebalance();

        super.rebalance();
    }

    ///
    /// @dev returns the health oracle address
    ///
    function healthOracle() external view returns (ICurvePoolHealth) {
        HealthOracleStorage storage $ = _getHealthOracleStorage();
        return $.healthOracle;
    }

    ///
    /// @param _healthOracle address of the health oracle
    /// @dev sets the health oracle address
    ///
    function setHealthOracle(address _healthOracle) external onlyOwner {
        HealthOracleStorage storage $ = _getHealthOracleStorage();
        $.healthOracle = ICurvePoolHealth(_healthOracle);
    }

    ///
    /// @dev stakes or unstakes LP tokens from Convex pools and removes liquidity from Curve pools
    /// @param amount token amount to deposit or withdraw
    ///
    function _genericInvestmentLogic(int256 amount) internal virtual override {
        BasePoolMetaStorage storage $ = _getBasePoolMetaStorage();

        BaseConstantsStorage storage $$ = _getBaseConstantsStorage();
        BasePoolStorage storage $$$ = _getBasePoolStorage();

        FijaStrategyStorage storage s = _getFijaStrategyStorage();

        CurveConvexLib._genericInvestmentLogic($, $$, $$$, s, amount);
    }

    ///
    /// @inheritdoc FijaStrategy
    ///
    function _allAssets() internal view virtual override returns (uint256) {
        return PERIPHERY.totalAssets();
    }

    ///
    /// @dev main harvest logic to fetch rewards and convert them to deposit ccy
    ///
    function _harvest() internal virtual override {
        HealthOracleStorage storage h = _getHealthOracleStorage();
        h.healthOracle.validateDepositWithdraw(false, false);

        BasePoolMetaStorage storage $ = _getBasePoolMetaStorage();
        BasePoolStorage storage $$ = _getBasePoolStorage();

        CurveConvexLib.harvest($, $$, POOL_NUM, PERIPHERY);
    }

    ///
    /// @dev converts all to deposit ccy to prepare for investment logic after going out from eme mode
    ///
    function _beforeEmeMode(bool turnOn) internal virtual override {
        BasePoolStorage storage $$ = _getBasePoolStorage();
        BaseConstantsStorage storage $ = _getBaseConstantsStorage();
        HealthOracleStorage storage h = _getHealthOracleStorage();

        h.healthOracle.validateEmeMode(
            $$._emergencyPool,
            $.EME_POOL_DISABLED,
            turnOn
        );

        if (!turnOn) {
            BasePoolMetaStorage storage $$$ = _getBasePoolMetaStorage();

            CurveConvexLib.beforeEmeMode($$$, $$, $, DEPOSIT_CCY);
        }
    }

    ///
    /// @dev converts all de-invested assets to emergency ccy
    ///
    function _afterEmeMode(bool turnOn) internal virtual override {
        if (turnOn) {
            BasePoolMetaStorage storage $$$ = _getBasePoolMetaStorage();
            BasePoolStorage storage $$ = _getBasePoolStorage();
            BaseConstantsStorage storage $ = _getBaseConstantsStorage();

            CurveConvexLib.afterEmeMode($$$, $$, $, DEPOSIT_CCY);
        }
    }

    receive() external payable override {}
}

