pragma solidity 0.8.28;

interface AggregatorV3Interface {
    function decimals() external view returns (uint8);

    function latestRoundData()
        external
        view
        returns (
            uint80 roundId,
            int256 answer,
            uint256 startedAt,
            uint256 updatedAt,
            uint80 answeredInRound
        );
}

/**
 * @notice Optional oracle pricing adapter (TWAP) for tokens not covered by Chainlink.
 * @dev Returns "denom per 1 token" scaled to 1e18.
 */
interface IUniswapFeedAdapter {
    function price1e18(
        address token,
        address source, // adapter-defined reference (e.g. UniV3 pool)
        address denomToken, // adapter-defined denom token (e.g. USDC for USD, WETH for ETH)
        uint32 twapWindow,
        bool invert
    ) external view returns (uint256);
}

/// @dev Uniswap V3 pool interface (minimal)
interface IUniswapV3Pool {
    function observe(
        uint32[] calldata secondsAgos
    )
        external
        view
        returns (
            int56[] memory tickCumulatives,
            uint160[] memory secondsPerLiquidityCumulativeX128s
        );

    function token0() external view returns (address);

    function token1() external view returns (address);

    function slot0()
        external
        view
        returns (
            uint160 sqrtPriceX96,
            int24 tick,
            uint16 observationIndex,
            uint16 observationCardinality,
            uint16 observationCardinalityNext,
            uint8 feeProtocol,
            bool unlocked
        );
}

// SPDX-License-Identifier: MIT
pragma solidity 0.8.28;

import {IERC20Metadata} from "@openzeppelin/contracts/token/ERC20/extensions/IERC20Metadata.sol";
import "./CurveOracleInterfaces.sol";

/**
 * @title CurveOracleRegistry
 * @notice Oracle pricing and cross-rate quoting.
 *
 * Features:
 *  - Chainlink price feeds (implemented)
 *  - Optional Uniswap TWAP oracle pricing adapter (plug-in)
 *  - USD<->ETH denom bridging via ethUsd config (optional)
 *
 * Conventions:
 *  - price1e18(token, denom) = denom per 1 token, scaled to 1e18
 *
 * Security:
 *  - Invalid or stale oracle answers revert (fail-closed).
 *  - Missing denom bridge when needed reverts.
 */
contract CurveOracleRegistry {
    uint256 internal constant PRECISION_18 = 1e18;
    address internal constant NATIVE_ETH = 0xEeeeeEeeeEeEeeEeEeEeeEEEeeeeEeeeeeeeEEeE;

    enum OracleType {
        CHAINLINK,
        UNISWAP
    }
    enum Denomination {
        USD,
        ETH
    }

    struct OracleConfig {
        OracleType oracleType;
        Denomination denom; // denom the token is priced in
        address source; // Chainlink feed OR Uniswap reference
        uint32 twapWindowUniswap; // Uniswap only
        uint32 maxStale; // Chainlink only (seconds). 0 disables staleness check.
        bool invert; // invert source price if needed (still 1e18)
        address denomTokenUniswap; // Uniswap only (adapter-defined)
    }

    error OracleInvalid();
    error OracleStale(address token, address oracle);
    error DenomBridgeNotSet();
    error UniswapAdapterNotSet();
    error UnsupportedOracleType();
    error ZeroAddress(string param);
    error EthUsdBridgeLivenessCheckFailed(address source);

    address public owner;
    IUniswapFeedAdapter public uniswapFeedAdapter;

    /**
     * @notice Bridge oracle used when converting USD-priced tokens to ETH denom (or vice versa).
     * @dev Typically configured as ETH/USD feed, denom=USD, invert=false.
     */
    OracleConfig public ethUsd;

    modifier onlyOwner() {
        require(msg.sender == owner, "not owner");
        _;
    }

    constructor(
        address _uniswapFeedAdapter, // can be address(0) initially
        OracleConfig memory _ethUsdBridge
    ) {
        owner = msg.sender;
        uniswapFeedAdapter = IUniswapFeedAdapter(_uniswapFeedAdapter);

        if (_ethUsdBridge.source != address(0)) {
            _verifyChainlinkLiveness(_ethUsdBridge.source);
        }
        ethUsd = _ethUsdBridge;
    }

    /**
     * @notice Transfer ownership.
     * @param newOwner Address of the new owner
     */
    function setOwner(address newOwner) external onlyOwner {
        if (newOwner == address(0)) revert ZeroAddress("owner");
        owner = newOwner;
    }

    /**
     * @notice Replace the Uniswap TWAP feed adapter.
     * @param addr Address of the new IUniswapFeedAdapter
     */
    function setUniswapPriceAdapter(address addr) external onlyOwner {
        uniswapFeedAdapter = IUniswapFeedAdapter(addr);
    }

    /**
     * @notice Replace the ETH/USD bridge oracle config.
     * @param cfg New OracleConfig for the ETH/USD bridge
     */
    function setEthUsdBridge(OracleConfig calldata cfg) external onlyOwner {
        if (cfg.source != address(0)) {
            _verifyChainlinkLiveness(cfg.source);
        }
        ethUsd = cfg;
    }

    /**
     * @notice Return price as (desiredDenom per 1 token), scaled to 1e18.
     * @dev If cfg.denom != desiredDenom, bridges via ethUsd (supports only USD<->ETH).
     * @param token The token to price
     * @param desiredDenom Target denomination (USD or ETH)
     * @param cfg Oracle configuration for the token
     * @return Price scaled to 1e18
     */
    function price1e18(
        address token,
        Denomination desiredDenom,
        OracleConfig memory cfg
    ) public view returns (uint256) {
        if (cfg.source == address(0)) revert OracleInvalid();

        // Direct denom case
        if (cfg.denom == desiredDenom) {
            return _readPrice1e18(token, cfg);
        }

        // Bridge denom case: must have ethUsd configured
        OracleConfig memory bridge = ethUsd;
        if (bridge.source == address(0)) revert DenomBridgeNotSet();

        // USD -> ETH: (USD/token) / (USD/ETH) = ETH/token
        if (cfg.denom == Denomination.USD && desiredDenom == Denomination.ETH) {
            uint256 tokenUsd = _readPrice1e18(token, cfg);
            uint256 ethUsdP = _readPrice1e18(address(0), bridge);
            return (tokenUsd * PRECISION_18) / ethUsdP;
        }

        // ETH -> USD: (ETH/token) * (USD/ETH) = USD/token
        if (cfg.denom == Denomination.ETH && desiredDenom == Denomination.USD) {
            uint256 tokenEth = _readPrice1e18(token, cfg);
            uint256 ethUsdP = _readPrice1e18(address(0), bridge);
            return (tokenEth * ethUsdP) / PRECISION_18;
        }

        revert OracleInvalid();
    }

    /**
     * @notice Oracle reference output for tokenIn -> tokenOut (exact-in), decimals-safe.
     * @dev Uses cfgIn.denom as common denom and bridges cfgOut if needed.
     * @param tokenIn Input token
     * @param tokenOut Output token
     * @param amountIn Exact input amount (in tokenIn decimals)
     * @param cfgIn Oracle configuration for tokenIn
     * @param cfgOut Oracle configuration for tokenOut
     * @return Expected output amount in tokenOut decimals
     */
    function quoteOut(
        address tokenIn,
        address tokenOut,
        uint256 amountIn,
        OracleConfig memory cfgIn,
        OracleConfig memory cfgOut
    ) external view returns (uint256) {
        Denomination common = cfgIn.denom;

        uint256 pIn = price1e18(tokenIn, common, cfgIn); // denom per 1 tokenIn
        uint256 pOut = price1e18(tokenOut, common, cfgOut); // denom per 1 tokenOut

        uint8 decIn = _tokenDecimals(tokenIn);
        uint8 decOut = _tokenDecimals(tokenOut);

        // Normalize amountIn to 1e18 "tokenIn units"
        uint256 amountInNorm = (amountIn * PRECISION_18) /
            (10 ** uint256(decIn));

        // Convert to denom value (1e18)
        uint256 denomValue = (amountInNorm * pIn) / PRECISION_18;

        // Convert denom value to tokenOut amount (1e18)
        uint256 amountOutNorm = (denomValue * PRECISION_18) / pOut;

        // Convert back to tokenOut decimals
        return (amountOutNorm * (10 ** uint256(decOut))) / PRECISION_18;
    }

    /**
     * @notice Return token decimals (18 for native ETH).
     * @param token Token address (or NATIVE_ETH sentinel)
     * @return Decimal count
     */
    function _tokenDecimals(address token) internal view returns (uint8) {
        if (token == NATIVE_ETH) return 18;
        return IERC20Metadata(token).decimals();
    }

    /**
     * @notice Verify a Chainlink feed returns valid data.
     * @dev Used at deploy/config time to catch misconfigured feed addresses early.
     */
    function _verifyChainlinkLiveness(address source) internal view {
        try AggregatorV3Interface(source).latestRoundData() returns (
            uint80,
            int256 answer,
            uint256,
            uint256,
            uint80
        ) {
            if (answer <= 0) revert EthUsdBridgeLivenessCheckFailed(source);
        } catch {
            revert EthUsdBridgeLivenessCheckFailed(source);
        }
    }

    /**
     * @notice Read price from configured oracle source, scaled to 1e18.
     * @dev Chainlink: latestRoundData + staleness guard. Uniswap: delegates to adapter (TWAP).
     * @param token The token being priced
     * @param cfg Oracle configuration (source, type, staleness, invert)
     * @return Price in cfg.denom per 1 token, scaled to 1e18
     */
    function _readPrice1e18(
        address token,
        OracleConfig memory cfg
    ) internal view returns (uint256) {
        if (cfg.oracleType == OracleType.CHAINLINK) {
            AggregatorV3Interface feed = AggregatorV3Interface(cfg.source);
            (, int256 ans, , uint256 updatedAt, ) = feed.latestRoundData();
            if (ans <= 0) revert OracleInvalid();

            if (cfg.maxStale != 0 && block.timestamp > updatedAt + cfg.maxStale)
                revert OracleStale(token, cfg.source);

            uint256 a = uint256(ans);
            uint8 feedDec = feed.decimals();

            // Scale to 1e18
            uint256 price = (feedDec <= 18)
                ? a * (10 ** (18 - feedDec))
                : a / (10 ** (feedDec - 18));

            // Optional inversion (still 1e18)
            if (cfg.invert) {
                return (PRECISION_18 * PRECISION_18) / price;
            }
            return price;
        }

        if (cfg.oracleType == OracleType.UNISWAP) {
            address ua = address(uniswapFeedAdapter);
            if (ua == address(0)) revert UniswapAdapterNotSet();
            return
                uniswapFeedAdapter.price1e18(
                    token,
                    cfg.source,
                    cfg.denomTokenUniswap,
                    cfg.twapWindowUniswap,
                    cfg.invert
                );
        }

        revert UnsupportedOracleType();
    }
}

