// SPDX-License-Identifier: MIT
pragma solidity 0.8.28;

import "./CurveOracleRegistry.sol";
import "./CurveAdapter.sol";
import "./CurveOracleTypes.sol";

/**
 * @title ICurvePoolHealth
 * @notice Interface for CurvePoolHealth - strategy-facing pool validator
 */
interface ICurvePoolHealth {
    // -------- View Functions --------

    /// @notice Get the owner address.
    function owner() external view returns (address);

    /// @notice Get the deposit currency address.
    function depositCcy() external view returns (address);

    /// @notice Get the oracle registry contract.
    function oracleRegistry() external view returns (CurveOracleRegistry);

    /// @notice Get the curve adapter contract.
    function curveAdapter() external view returns (CurveAdapter);

    /// @notice Whether depeg check is enabled.
    function depegCheck() external view returns (bool);

    /**
     * @notice Get normal peg band for a pool/coin pair.
     * @param pool The pool address
     * @param coin The coin address
     * @return The peg band in bps
     */
    function pegBandNormal(
        address pool,
        address coin
    ) external view returns (uint16);

    /**
     * @notice Get emergency peg band for a pool/coin pair.
     * @param pool The pool address
     * @param coin The coin address
     * @return The peg band in bps
     */
    function pegBandEmergency(
        address pool,
        address coin
    ) external view returns (uint16);

    /**
     * @notice Get probe amount for a token.
     * @param token The token address
     * @return The probe amount used for quoting
     */
    function probeAmount(address token) external view returns (uint256);

    /**
     * @notice Get full pool configuration struct.
     * @param pool The pool address
     * @return The complete PoolConfigCore struct
     */
    function getPoolConfig(
        address pool
    ) external view returns (PoolConfigCore memory);

    /**
     * @notice Get all coins for a Curve pool.
     * @param pool The pool address
     * @return Array of coin addresses in Curve index order
     */
    function getCurvePoolCoins(
        address pool
    ) external view returns (address[] memory);

    /**
     * @notice Get coin at index for a Curve pool.
     * @param pool The pool address
     * @param index The coin index
     * @return The coin address at the given index
     */
    function getCurvePoolCoin(
        address pool,
        uint256 index
    ) external view returns (address);

    /**
     * @notice Get oracle configuration for a coin.
     * @param coin The coin address
     * @return The complete OracleConfig struct
     */
    function getCoinOracle(
        address coin
    ) external view returns (CurveOracleRegistry.OracleConfig memory);

    /**
     * @notice Check if a pool is enabled.
     * @param pool The pool address
     * @return True if the pool is enabled
     */
    function isPoolEnabled(address pool) external view returns (bool);

    // -------- Validation Functions --------

    /**
     * @notice Validate pools before a user deposit or withdrawal.
     * @dev Normal-mode deposit (isEmergency=false, isDeposit=true):
     *        depeg (Chainlink, normal bands) + quote check (normal thresholds).
     *      Normal-mode withdrawal (isEmergency=false, isDeposit=false):
     *        quote check with adaptive thresholds — depeg is NOT checked so
     *        users can always exit. If a peg deviation is detected the quote
     *        check uses peg thresholds (wider) so the oracle cross-rate shift
     *        from the depeg does not block the withdrawal; otherwise normal
     *        thresholds apply.
     *      Emergency-mode withdrawal (isEmergency=true):
     *        quote check only (emergency thresholds) — sandwich protection for
     *        withdrawals without blocking on the active depeg.
     * @param isDeposit True for deposit direction, false for withdraw
     * @param isEmergency True when strategy is in emergency mode
     * @dev Reverts with PoolHealthValidationFailedPeg or PoolHealthValidationFailedQuote on failure.
     */
    function validateDepositWithdraw(bool isDeposit, bool isEmergency) external view returns (bool);

    /**
     * @notice Decide whether emergency mode should be activated.
     * @dev Only uses sandwich-resistant signals: depeg via Chainlink oracles
     *      (off-chain, not manipulable on-chain). Quote checks are excluded
     *      because they read on-chain pool state that an attacker can distort
     *      to force a false emergency trigger.
     * @return ok True when all pools are healthy (no emergency needed)
     */
    function validateNeedEmeMode() external view returns (bool ok);

    /**
     * @notice Guard for emergency mode transitions — checks pool execution
     *         quotes against Chainlink oracle to detect sandwich attacks.
     * @dev Direction-aware validation matching the actual on-chain operations:
     *
     *      goToEmeMode = true  (entering emergency mode):
     *        1. Emergency pool swap: depositCcy → emergencyCcy (ADD_ONE_COIN).
     *        2. Deinvest from all pools: REMOVE_ONE_COIN.
     *        If a depeg triggered the emergency entry, peg thresholds (wider)
     *        are used so the oracle cross-rate shift does not block the transition.
     *
     *      goToEmeMode = false (exiting emergency mode):
     *        1. Emergency pool swap: emergencyCcy → depositCcy (REMOVE_ONE_COIN).
     *        2. Invest into all pools: ADD_ONE_COIN.
     *
     *      When isEmePoolDisabled is true the emergency pool swap check is
     *      skipped (strategy holds assets in depositCcy during emergency mode).
     *
     *      Peg is checked as a soft signal (non-reverting): if a depeg is
     *      detected when entering emergency mode, thresholds widen to PEG mode
     *      so the oracle cross-rate shift does not block the transition.
     * @param emergencyPool Address of the pool used for depositCcy/emergencyCcy swap
     * @param isEmePoolDisabled True when the emergency pool swap is disabled
     * @param goToEmeMode True when entering emergency mode, false when exiting
     * @dev Reverts with PoolHealthValidationFailedQuote on failure.
     */
    function validateEmeMode(
        address emergencyPool,
        bool isEmePoolDisabled,
        bool goToEmeMode
    ) external view returns (bool);

    /**
     * @notice Guard for rebalance — checks depeg and execution quotes in both
     *         ADD and REMOVE directions with normal thresholds.
     * @dev Rebalance removes liquidity from over-exposed pools and adds to
     *      under-exposed pools, so both directions are validated. Uses normal
     *      thresholds since rebalance is blocked during emergency mode.
     *      Reverts with PoolHealthValidationFailedPeg or PoolHealthValidationFailedQuote on failure.
     */
    function validateRebalance() external view returns (bool);

    // -------- Admin Functions --------

    /**
     * @notice Set a new owner.
     * @param newOwner The new owner address
     */
    function setOwner(address newOwner) external;

    /**
     * @notice Set the oracle registry contract.
     * @param _oracleRegistry The new oracle registry address
     */
    function setOracleRegistry(address _oracleRegistry) external;

    /**
     * @notice Set the curve adapter contract.
     * @param _curveAdapter The new curve adapter address
     */
    function setCurveAdapter(address _curveAdapter) external;

    /**
     * @notice Set probe amount for a token.
     * @param token The token address
     * @param amount The probe amount
     */
    function setProbeAmount(address token, uint256 amount) external;

    /**
     * @notice Set oracle config for a coin.
     * @param coin The coin address
     * @param cfg The oracle configuration
     */
    function setCoinOracle(
        address coin,
        CurveOracleRegistry.OracleConfig calldata cfg
    ) external;

    /**
     * @notice Set pool configuration.
     * @param pool The pool address
     * @param cfg The pool configuration
     */
    function setPoolConfig(address pool, PoolConfigCore calldata cfg) external;

    /**
     * @notice Set coins for a Curve pool.
     * @param curvePool The pool address
     * @param coins The ordered list of coin addresses
     */
    function setCurvePoolCoins(
        address curvePool,
        address[] calldata coins
    ) external;

    /**
     * @notice Set peg bands for a pool/coin pair.
     * @param pool The pool address
     * @param coin The coin address
     * @param normalBps Normal mode peg band in bps
     * @param emergencyBps Emergency mode peg band in bps
     */
    function setPegBand(
        address pool,
        address coin,
        uint16 normalBps,
        uint16 emergencyBps
    ) external;

    /**
     * @notice Enable or disable a pool for validation.
     * @param pool The pool address
     * @param isEnabled Whether the pool should be enabled
     */
    function setPoolEnabled(address pool, bool isEnabled) external;

    /**
     * @notice Enable or disable depeg check.
     * @param isEnabled Whether depeg check should be enabled
     */
    function setDepegCheck(bool isEnabled) external;
}

