contracts/strategies/CurveConvex/CurveAd.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.28;

import "../../protocols/curve/interfaces/ICurve.sol";

/**
 * @title CurveAdapter
 * @notice Read-only adapter for Curve pool reads:
 *  - poolQuote(): exact-in quote using get_dy variants
 *  - balances(): pool balances aligned to configured coin index order
 *
 * interfaceId is your dispatcher so you can support different pool ABIs.
 */
contract CurveAdapter {
    // ----- Quote ABIs -----

    error UnsupportedInterfaceId();
    error TokenNotInPool();

    /**
     * @notice Return marginal pool quote for tokenIn -> tokenOut for amountIn (exact-in).
     * @param pool Curve pool address
     * @param interfaceId Dispatcher for which ABI to use
     * @param coins Ordered pool coins (index order MUST match Curve indices)
     * @param tokenIn Input token
     * @param tokenOut Output token
     * @param amountIn Input amount
     * @return amountOut Output amount in tokenOut decimals
     */
    function poolQuote(
        address pool,
        uint32 interfaceId,
        address[] memory coins,
        address tokenIn,
        address tokenOut,
        uint256 amountIn
    ) external view returns (uint256 amountOut) {
        (int128 i, int128 j) = _findIndices(coins, tokenIn, tokenOut);

        // interfaceId mapping (example):
        //  1 => get_dy
        //  2 => get_dy_underlying
        if (interfaceId == 1) {
            return
                ICurve(pool).get_dy(
                    uint256(uint128(i)),
                    uint256(uint128(j)),
                    amountIn
                );
        }
        if (interfaceId == 6) {
            return ICurve(pool).get_dy(i, j, amountIn);
        }

        revert UnsupportedInterfaceId();
    }

    /**
     * @notice Read pool balances aligned to `coins` order.
     * @dev Default assumes balances(uint256). Extend by interfaceId for different ABIs.
     * @param pool Curve pool address
     * @param interfaceId ABI variant selector (0 reverts as guard)
     * @param coins Ordered coin addresses matching Curve indices
     * @return out Balance array aligned to coins order
     */
    function balances(
        address pool,
        uint32 interfaceId,
        address[] memory coins
    ) external view returns (uint256[] memory out) {
        if (interfaceId == 0) revert UnsupportedInterfaceId(); // optional guard

        out = new uint256[](coins.length);
        for (uint256 idx = 0; idx < coins.length; idx++) {
            out[idx] = ICurve(pool).balances(idx);
        }
    }

    /**
     * @notice Resolve Curve pool indices for a (tokenIn, tokenOut) pair.
     * @param coins Ordered pool coin addresses
     * @param tokenIn Input token to find
     * @param tokenOut Output token to find
     * @return i Curve index of tokenIn
     * @return j Curve index of tokenOut
     */
    function _findIndices(
        address[] memory coins,
        address tokenIn,
        address tokenOut
    ) internal pure returns (int128 i, int128 j) {
        int128 ii = -1;
        int128 jj = -1;

        for (uint256 k = 0; k < coins.length; k++) {
            if (coins[k] == tokenIn) ii = int128(int256(k));
            if (coins[k] == tokenOut) jj = int128(int256(k));
        }

        if (ii < 0 || jj < 0) revert TokenNotInPool();
        return (ii, jj);
    }
}

