import "../../base/FijaStrategy.sol";

library CurveConvexLib {
    /// @dev Struct to pack withdrawal calculation values and reduce stack usage
    struct WithdrawVars {
        address pool;
        int128 depositCcyIndex;
        address rewardContract;
        uint256 slippage;
        uint256 lpTokensToWithdraw;
        uint256 minOut;
    }

    error FijaEmeModeInvalidQuote();

    ///
    /// @dev Helper for providing liquidity to Curve pools
    /// Used to brige difference in pool interfaces
    /// @param pool address to which liquidity is provided
    /// @param depositAmount amount in deposit tokens to provide to liquidity pools
    /// @param minMintAmount minimum amount of LP token expected to receive
    /// NOTE: some pool require use of special deposit contracts for operations
    ///
    function _addLiquidity(
        CurveConvexBase.BasePoolMetaStorage storage $,
        address depositCcy,
        address pool,
        uint256 depositAmount,
        uint256 minMintAmount
    ) public {
        uint8 id = $._poolCategory[pool][0];
        int128 depositCcyIndex = $._poolDepositCcyIndex[pool];

        uint256[4] memory amounts = CurveConvexConstants._buildInputAmount(
            depositAmount,
            depositCcyIndex
        );

        address origPool;
        address depositCtr = $._poolDepositCtr[pool];
        if (depositCtr != address(0)) {
            origPool = pool;
            pool = depositCtr;
        }
        if (id == 0) {
            uint256 ethValue = 0;
            if (depositCcy == CurveConvexConstants.ETH) {
                ethValue = depositAmount;
            }
            uint256[3] memory inputs = [amounts[0], amounts[1], amounts[2]];

            ICurve(pool).add_liquidity{value: ethValue}(inputs, minMintAmount);
        } else if (id == 1) {
            uint256[3] memory inputs = [amounts[0], amounts[1], amounts[2]];

            uint256 ethValue = 0;
            if (depositCcy == CurveConvexConstants.ETH) {
                ethValue = depositAmount;
            }
            ICurve(pool).add_liquidity{value: ethValue}(
                inputs,
                minMintAmount,
                true
            );
        } else if (id == 2) {
            uint256[2] memory inputs = [amounts[0], amounts[1]];

            uint256 ethValue = 0;
            if (depositCcy == CurveConvexConstants.ETH) {
                ethValue = depositAmount;
            }
            ICurve(pool).add_liquidity{value: ethValue}(inputs, minMintAmount);
        } else if (id == 3) {
            ICurve(pool).add_liquidity(amounts, minMintAmount);
        } else if (id == 4) {
            uint256[2] memory inputs = [amounts[0], amounts[1]];

            uint256 ethValue = 0;
            if (depositCcy == CurveConvexConstants.ETH) {
                ethValue = depositAmount;
            }

            ICurve(pool).add_liquidity{value: ethValue}(
                inputs,
                minMintAmount,
                true
            );
        } else if (id == 5) {
            ICurve(pool).add_liquidity(origPool, amounts, minMintAmount);
        } else if (id == 6) {
            uint256[3] memory inputs = [amounts[0], amounts[1], amounts[2]];
            ICurve(pool).add_liquidity(origPool, inputs, minMintAmount);
        } else if (id == 7) {
            uint256[] memory inputs = new uint256[](2);

            inputs[0] = amounts[0];
            inputs[1] = amounts[1];

            ICurve(pool).add_liquidity(inputs, minMintAmount);
        } else {
            revert FijaInvalidPoolCategory();
        }
    }

    ///
    /// @dev Helper for calculating amount of deposit tokens to receive when burning LP tokens
    /// Used to brige difference in pool interfaces
    /// @param pool address of Curve liquidity pool which holds LP tokens
    /// @param burnAmount amount of LP tokens to burn
    /// @param minReceived minimum amount of deposit tokens expected to receive
    /// NOTE: some pool require use of special deposit contracts for operations
    ///
    function _removeLiquidityOneCoin(
        CurveConvexBase.BasePoolMetaStorage storage $,
        address pool,
        uint256 burnAmount,
        uint256 minReceived
    ) public {
        uint8 id = $._poolCategory[pool][1];
        address depositCtr = $._poolDepositCtr[pool];

        int128 i = $._poolDepositCcyIndex[pool];

        address origPool;
        if (depositCtr != address(0)) {
            origPool = pool;
            pool = depositCtr;
        }
        if (id == 0) {
            ICurve(pool).remove_liquidity_one_coin(burnAmount, i, minReceived);
        } else if (id == 1) {
            ICurve(pool).remove_liquidity_one_coin(
                burnAmount,
                i,
                minReceived,
                true
            );
        } else if (id == 2) {
            ICurve(pool).remove_liquidity_one_coin(
                burnAmount,
                uint256(int256(i)),
                minReceived,
                true
            );
        } else if (id == 3) {
            ICurve(pool).remove_liquidity_one_coin(
                burnAmount,
                uint256(int256(i)),
                minReceived
            );
        } else if (id == 4) {
            ICurve(pool).remove_liquidity_one_coin(
                origPool,
                burnAmount,
                i,
                minReceived
            );
        } else {
            revert FijaInvalidPoolCategory();
        }
    }

    ///
    /// @dev stakes or unstakes LP tokens from Convex pools and removes liquidity from Curve pools
    /// @param amount token amount to deposit or withdraw
    ///
    function _genericInvestmentLogic(
        CurveConvexBase.BasePoolMetaStorage storage $,
        CurveConvexBase.BaseConstantsStorage storage $$,
        CurveConvexBase.BasePoolStorage storage $$$,
        FijaStrategy.FijaStrategyStorage storage s,
        int256 amount
    ) external {
        if (amount > 0) {
            // DEPOSIT

            ICurveConvexPeriphery periphery = ICurveConvexStrategy(
                address(this)
            ).PERIPHERY();

            // find lowest negative difference between target and current exposure
            (int256[8] memory poolExpDiff, ) = periphery.exposureDiff(
                periphery.totalAssets()
            );
            address depositCcy = ICurveConvexStrategy(address(this))
                .DEPOSIT_CCY();

            uint256 remainingToDeposit = uint256(amount);

            while (remainingToDeposit > 0) {
                uint8 minIndex = 0;
                int256 minDiff = 0;
                {
                    uint8 poolNum = ICurveConvexStrategy(address(this))
                        .POOL_NUM();
                    for (uint8 i = 0; i < poolNum; i++) {
                        if (poolExpDiff[i] < minDiff) {
                            minDiff = poolExpDiff[i];
                            minIndex = i;
                        }
                    }
                }
                if (minDiff < 0) {
                    uint256 assetsToDeposit = 0;
                    if (int256(remainingToDeposit) + minDiff <= 0) {
                        // deposit all assets to pool
                        assetsToDeposit = remainingToDeposit;
                        remainingToDeposit = 0;
                    } else {
                        // deposit difference
                        assetsToDeposit = uint256(minDiff * -1);
                        remainingToDeposit -= assetsToDeposit;

                        // reduce deposited exposure
                        poolExpDiff[minIndex] = 0;
                    }
                    address pool = $$$._curvePools[minIndex];

                    {
                        uint256 minAmount = periphery.calcTokenAmount(
                            pool,
                            assetsToDeposit,
                            true
                        );
                        minAmount =
                            (minAmount *
                                (CurveConvexConstants.BASIS_POINTS_DIVISOR -
                                    $$.SLIPPAGE_SWAP)) /
                            CurveConvexConstants.BASIS_POINTS_DIVISOR;
                        {
                            address depositCtr = $._poolDepositCtr[pool];
                            if (depositCcy != CurveConvexConstants.ETH) {
                                SafeERC20.forceApprove(
                                    IERC20(depositCcy),
                                    depositCtr != address(0)
                                        ? depositCtr
                                        : pool,
                                    assetsToDeposit
                                );
                            }
                        }
                        address lpToken = $._poolLpToken[pool];

                        // deposit to curve pools to get LP tokens
                        _addLiquidity(
                            $,
                            depositCcy,
                            pool,
                            assetsToDeposit,
                            minAmount
                        );

                        SafeERC20.forceApprove(
                            IERC20(lpToken),
                            address(CurveConvexConstants.Convex_IBooster),
                            IERC20(lpToken).balanceOf(address(this))
                        );
                    }
                    // stake all LPtokens to convex
                    CurveConvexConstants.Convex_IBooster.depositAll(
                        $._poolConvexPoolId[pool],
                        true
                    );
                } else {
                    // no positive discrepancy, so end logic
                    remainingToDeposit = 0;
                }
            }
        } else if (amount < 0) {
            // WITHDRAW

            uint256 remainingToWithdraw = uint256(-amount);

            if (!s._isEmergencyMode) {
                uint256 currentBalance;
                {
                    address depositCcy = ICurveConvexStrategy(address(this))
                        .DEPOSIT_CCY();

                    if (depositCcy == CurveConvexConstants.ETH) {
                        currentBalance = address(this).balance;
                    } else {
                        currentBalance = IERC20(depositCcy).balanceOf(
                            address(this)
                        );
                    }
                }

                ICurveConvexPeriphery periphery = ICurveConvexStrategy(
                    address(this)
                ).PERIPHERY();

                int256[8] memory poolExpDiff;
                {
                    uint256 targetExposure;

                    uint256 _totalAssets = periphery.totalAssets();

                    // TODO sometimes this is negative when draining the strategy
                    // when user withdraws  maxWithdraw then it is ok
                    // if I assert "amount" requested here is < maxWithdraw then I get fail on EmeMode
                    // this solution is half way to keep eme mode ok and to give user good response
                    if (_totalAssets < remainingToWithdraw) {
                        revert FijaExceededMaxWithdraw();
                    }

                    if (_totalAssets - remainingToWithdraw < currentBalance) {
                        revert FijaExceededMaxWithdraw();
                    }

                    targetExposure =
                        _totalAssets -
                        remainingToWithdraw -
                        currentBalance;

                    (poolExpDiff, ) = periphery.exposureDiff(targetExposure);
                }

                while (remainingToWithdraw > 0) {
                    uint8 maxIndex = 0;
                    int256 maxDiff = 0;

                    // find biggest positive difference between target and current exposure
                    {
                        uint8 poolNum = ICurveConvexStrategy(address(this))
                            .POOL_NUM();
                        for (uint8 i = 0; i < poolNum; i++) {
                            if (poolExpDiff[i] > maxDiff) {
                                maxDiff = poolExpDiff[i];
                                maxIndex = i;
                            }
                        }
                    }

                    if (maxDiff > 0) {
                        uint256 assetsToWithdraw = 0;
                        if (int256(remainingToWithdraw) - maxDiff <= 0) {
                            // withdraw all assets from the pool
                            assetsToWithdraw = remainingToWithdraw;
                            remainingToWithdraw = 0;
                        } else {
                            // withdraw difference
                            assetsToWithdraw = uint256(maxDiff);
                            remainingToWithdraw -= assetsToWithdraw;

                            // reduce deposited exposure
                            poolExpDiff[maxIndex] = 0;
                        }
                        WithdrawVars memory v;
                        v.pool = $$$._curvePools[maxIndex];
                        v.depositCcyIndex = $._poolDepositCcyIndex[v.pool];
                        v.rewardContract = $._poolRewardContract[v.pool];
                        v.slippage = $$.SLIPPAGE_SWAP;
                        {
                            // Calculate initial LP tokens estimate
                            v.lpTokensToWithdraw = periphery.calcTokenAmount(
                                v.pool,
                                assetsToWithdraw,
                                false
                            );
                            // Calibrate LP tokens for single-sided withdrawal
                            uint256 actualOut = periphery.calcWithdrawOneCoin(
                                v.pool,
                                v.lpTokensToWithdraw,
                                v.depositCcyIndex
                            );
                            if (actualOut > 0 && actualOut < assetsToWithdraw) {
                                v.lpTokensToWithdraw =
                                    (v.lpTokensToWithdraw *
                                        assetsToWithdraw *
                                        (CurveConvexConstants
                                            .BASIS_POINTS_DIVISOR +
                                            v.slippage)) /
                                    (actualOut *
                                        CurveConvexConstants
                                            .BASIS_POINTS_DIVISOR);
                            } else {
                                v.lpTokensToWithdraw =
                                    (v.lpTokensToWithdraw *
                                        (CurveConvexConstants
                                            .BASIS_POINTS_DIVISOR +
                                            v.slippage)) /
                                    CurveConvexConstants.BASIS_POINTS_DIVISOR;
                            }
                            v.minOut = assetsToWithdraw;
                        }
                        {
                            // check if we are burning more than we have
                            uint256 lpTokenBalance = IERC20(v.rewardContract)
                                .balanceOf(address(this));
                            if (v.lpTokensToWithdraw > lpTokenBalance) {
                                v.lpTokensToWithdraw = lpTokenBalance;
                                v.minOut = periphery.calcWithdrawOneCoin(
                                    v.pool,
                                    v.lpTokensToWithdraw,
                                    v.depositCcyIndex
                                );
                                v.minOut =
                                    (v.minOut *
                                        (CurveConvexConstants
                                            .BASIS_POINTS_DIVISOR -
                                            v.slippage)) /
                                    CurveConvexConstants.BASIS_POINTS_DIVISOR;
                            }
                            IRewardStaking(v.rewardContract).withdrawAndUnwrap(
                                v.lpTokensToWithdraw,
                                false
                            );
                        }
                        {
                            // special approval for deposit zaps
                            address depositCtr = $._poolDepositCtr[v.pool];
                            if (depositCtr != address(0)) {
                                SafeERC20.forceApprove(
                                    IERC20($._poolLpToken[v.pool]),
                                    depositCtr,
                                    v.lpTokensToWithdraw
                                );
                            }
                        }
                        // liquidate lp tokens on curve to get deposit currency out
                        _removeLiquidityOneCoin(
                            $,
                            v.pool,
                            v.lpTokensToWithdraw,
                            v.minOut
                        );
                    } else {
                        remainingToWithdraw = 0;
                    }
                }
            } else {
                address depositCcy = ICurveConvexStrategy(address(this))
                    .DEPOSIT_CCY();

                ICurveConvexPeriphery periphery = ICurveConvexStrategy(
                    address(this)
                ).PERIPHERY();
                // in emergency mode, convert emergency to deposit and withdraw
                address emergencyCcy = $$.EMERGENCY_CCY;
                uint256 exAmount = periphery.getExchangeAmount(
                    $$$._emergencyPool,
                    depositCcy,
                    emergencyCcy,
                    remainingToWithdraw
                );
                if (exAmount == 0) {
                    revert FijaInsufficientAmountToWithdraw();
                }

                uint256 emergencyCCyAmount = (exAmount *
                    (CurveConvexConstants.BASIS_POINTS_DIVISOR +
                        $$.SLIPPAGE_EMERGENCY)) /
                    CurveConvexConstants.BASIS_POINTS_DIVISOR;

                // check if we have enough of emergencyCcy
                uint256 emergencyCcyBalance = IERC20(emergencyCcy).balanceOf(
                    address(this)
                );
                if (emergencyCCyAmount > emergencyCcyBalance) {
                    emergencyCCyAmount = emergencyCcyBalance;
                    remainingToWithdraw =
                        (remainingToWithdraw *
                            (CurveConvexConstants.BASIS_POINTS_DIVISOR -
                                $$.SLIPPAGE_EMERGENCY)) /
                        CurveConvexConstants.BASIS_POINTS_DIVISOR;
                }

                CurveConvexExchangeLib._exchange(
                    $,
                    $$$._emergencyPool,
                    emergencyCcy,
                    depositCcy,
                    emergencyCCyAmount,
                    remainingToWithdraw
                );
            }
        } else {
            // REBALANCE

            ICurveConvexPeriphery periphery = ICurveConvexStrategy(
                address(this)
            ).PERIPHERY();
            (int256[8] memory poolExpDiff, ) = periphery.exposureDiff(
                IERC4626(address(this)).totalAssets()
            );

            // first settle the positives, reduction of exposure
            uint8 poolNum = ICurveConvexStrategy(address(this)).POOL_NUM();
            for (uint8 i = 0; i < poolNum; i++) {
                if (poolExpDiff[i] > 0) {
                    WithdrawVars memory v;
                    v.pool = $$$._curvePools[i];
                    v.depositCcyIndex = $._poolDepositCcyIndex[v.pool];
                    v.rewardContract = $._poolRewardContract[v.pool];
                    v.slippage = $$.SLIPPAGE_SWAP;
                    {
                        uint256 targetOut = uint256(poolExpDiff[i]);
                        // Calculate initial LP tokens estimate
                        v.lpTokensToWithdraw = periphery.calcTokenAmount(
                            v.pool,
                            targetOut,
                            false
                        );
                        // Calibrate LP tokens for single-sided withdrawal
                        uint256 actualOut = periphery.calcWithdrawOneCoin(
                            v.pool,
                            v.lpTokensToWithdraw,
                            v.depositCcyIndex
                        );
                        if (actualOut > 0 && actualOut < targetOut) {
                            v.lpTokensToWithdraw =
                                (v.lpTokensToWithdraw *
                                    targetOut *
                                    (CurveConvexConstants.BASIS_POINTS_DIVISOR +
                                        v.slippage)) /
                                (actualOut *
                                    CurveConvexConstants.BASIS_POINTS_DIVISOR);
                        } else {
                            v.lpTokensToWithdraw =
                                (v.lpTokensToWithdraw *
                                    (CurveConvexConstants.BASIS_POINTS_DIVISOR +
                                        v.slippage)) /
                                CurveConvexConstants.BASIS_POINTS_DIVISOR;
                        }
                        v.minOut = targetOut;
                    }

                    {
                        // check if we are burning more than we have
                        uint256 lpTokenBalance = IERC20(v.rewardContract)
                            .balanceOf(address(this));
                        if (v.lpTokensToWithdraw > lpTokenBalance) {
                            v.lpTokensToWithdraw = lpTokenBalance;
                            v.minOut = periphery.calcWithdrawOneCoin(
                                v.pool,
                                v.lpTokensToWithdraw,
                                v.depositCcyIndex
                            );
                            v.minOut =
                                (v.minOut *
                                    (CurveConvexConstants.BASIS_POINTS_DIVISOR -
                                        v.slippage)) /
                                CurveConvexConstants.BASIS_POINTS_DIVISOR;
                        }
                        IRewardStaking(v.rewardContract).withdrawAndUnwrap(
                            v.lpTokensToWithdraw,
                            false
                        );
                    }

                    {
                        // special approve for deposit zaps
                        address depositCtr = $._poolDepositCtr[v.pool];
                        if (depositCtr != address(0)) {
                            SafeERC20.forceApprove(
                                IERC20($._poolLpToken[v.pool]),
                                depositCtr,
                                v.lpTokensToWithdraw
                            );
                        }
                    }
                    // liquidate lp tokens on curve
                    _removeLiquidityOneCoin(
                        $,
                        v.pool,
                        v.lpTokensToWithdraw,
                        v.minOut
                    );
                }
            }
            address depositCcy = ICurveConvexStrategy(address(this))
                .DEPOSIT_CCY();

            // second settle the negatives, increase of exposure
            for (uint8 i = 0; i < poolNum; i++) {
                address pool = $$$._curvePools[i];

                if (poolExpDiff[i] < 0) {
                    uint256 assetsToDeposit = uint256(poolExpDiff[i] * -1);

                    if (depositCcy != CurveConvexConstants.ETH) {
                        address depositCtr = $._poolDepositCtr[pool];
                        SafeERC20.forceApprove(
                            IERC20(depositCcy),
                            depositCtr != address(0) ? depositCtr : pool,
                            assetsToDeposit
                        );
                    }
                    uint256 minOut = periphery.calcTokenAmount(
                        pool,
                        assetsToDeposit,
                        true
                    );
                    minOut =
                        (minOut *
                            (CurveConvexConstants.BASIS_POINTS_DIVISOR -
                                $$.SLIPPAGE_SWAP)) /
                        CurveConvexConstants.BASIS_POINTS_DIVISOR;

                    address lpToken = $._poolLpToken[pool];

                    _addLiquidity($, depositCcy, pool, assetsToDeposit, minOut);

                    SafeERC20.forceApprove(
                        IERC20(lpToken),
                        address(CurveConvexConstants.Convex_IBooster),
                        IERC20(lpToken).balanceOf(address(this))
                    );
                    // stake LPtokens to convex
                    CurveConvexConstants.Convex_IBooster.depositAll(
                        $._poolConvexPoolId[pool],
                        true
                    );
                }
            }
            emit FijaStrategyEvents.Rebalance(block.timestamp, "");
        }
    }

    ///
    /// @dev gets various strategy status parameters
    /// @return status parameters as string
    ///
    function status(
        CurveConvexBase.BasePoolMetaStorage storage $,
        CurveConvexBase.BasePoolStorage storage $$,
        CurveConvexBase.BaseConstantsStorage storage c,
        address depositCcy,
        uint8 poolNum
    ) external view returns (string memory) {
        ICurveConvexPeriphery periphery = ICurveConvexStrategy(address(this))
            .PERIPHERY();

        string memory str2 = "";

        uint256 crvEarned = 0;
        {
            for (uint8 i = 0; i < poolNum; i++) {
                address pool = $$._curvePools[i];

                uint256 poolValue = periphery.calcWithdrawOneCoin(
                    pool,
                    IERC20($._poolRewardContract[pool]).balanceOf(
                        address(this)
                    ),
                    $._poolDepositCcyIndex[pool]
                );
                str2 = string(
                    abi.encodePacked(
                        str2,
                        "|Pool:",
                        Strings.toHexString(uint256(uint160(pool)), 20),
                        "|LpTokens:",
                        Strings.toString(
                            IERC20($._poolRewardContract[pool]).balanceOf(
                                address(this)
                            )
                        ),
                        "|Value:",
                        Strings.toString(poolValue)
                    )
                );

                (, , , address rewardContract, , ) = CurveConvexConstants
                    .Convex_IBooster
                    .poolInfo($._poolConvexPoolId[pool]);
                crvEarned += IRewardStaking(rewardContract).earned(
                    address(this)
                );
            }
        }

        uint256 emergencyCCyValue = 0;

        uint256 depositCCyValue;

        if (!c.EME_POOL_DISABLED) {
            emergencyCCyValue = IERC20(c.EMERGENCY_CCY).balanceOf(
                address(this)
            );
        }
        if (depositCcy == CurveConvexConstants.ETH) {
            depositCCyValue = address(this).balance;
        } else {
            depositCCyValue = IERC20(depositCcy).balanceOf(address(this));
        }

        (uint256[2] memory crvCvxInDeposit, , ) = periphery.crvCvxToDepositCcy(
            [
                crvEarned,
                CurveConvexConstants.Convex_ICvxMining.ConvertCrvToCvx(
                    crvEarned
                )
            ]
        );

        string memory str1 = string(
            abi.encodePacked(
                "totalAssets:",
                Strings.toString(IERC4626(address(periphery)).totalAssets())
            )
        );

        return
            string(
                abi.encodePacked(
                    str1,
                    "|UnclaimedRewards:",
                    Strings.toString(crvCvxInDeposit[0] + crvCvxInDeposit[1]),
                    "|DepositCcyAmount:",
                    Strings.toString(depositCCyValue),
                    "|EmergencyCcyAmount:",
                    c.EME_POOL_DISABLED
                        ? "N/A"
                        : Strings.toString(emergencyCCyValue),
                    str2
                )
            );
    }

    ///
    /// @dev main harvest logic to fetch rewards and convert them to deposit ccy
    /// @param $ BasePoolMetaStorage reference
    /// @param $$ BasePoolStorage reference
    /// @param poolNum number of pools in the strategy
    /// @param periphery reference to periphery contract
    ///
    function harvest(
        CurveConvexBase.BasePoolMetaStorage storage $,
        CurveConvexBase.BasePoolStorage storage $$,
        uint8 poolNum,
        ICurveConvexPeriphery periphery
    ) external {
        // get rewards from each pool
        for (uint8 i = 0; i < poolNum; i++) {
            IRewardStaking($._poolRewardContract[$$._curvePools[i]]).getReward(
                address(this),
                false
            );
        }
        // convert CRV and CVX rewards to deposit currency
        uint256 crvAmount = IERC20(CurveConvexConstants.CRV).balanceOf(
            address(this)
        );
        uint256 cvxAmount = IERC20(CurveConvexConstants.CVX).balanceOf(
            address(this)
        );
        (
            uint256[2] memory output,
            uint256[] memory crvIntermed,
            uint256[] memory cvxIntermed
        ) = periphery.crvCvxToDepositCcy([crvAmount, cvxAmount]);

        if (output[0] != 0 && crvAmount != 0) {
            uint8 crvPoolNum = uint8($$._crvRewardRoute.length);
            // calculate CRV to deposit currency amount
            for (uint8 i = 0; i < crvPoolNum; i++) {
                crvAmount = CurveConvexExchangeLib._exchange(
                    $,
                    $$._crvRewardRoute[i].addr,
                    $$._crvRewardRoute[i].from,
                    $$._crvRewardRoute[i].to,
                    crvAmount,
                    crvIntermed[i]
                );
            }
        }
        if (output[1] != 0 && cvxAmount != 0) {
            uint8 cvxPoolNum = uint8($$._cvxRewardRoute.length);
            // calculate CVX to deposit currency amount
            for (uint8 i = 0; i < cvxPoolNum; i++) {
                cvxAmount = CurveConvexExchangeLib._exchange(
                    $,
                    $$._cvxRewardRoute[i].addr,
                    $$._cvxRewardRoute[i].from,
                    $$._cvxRewardRoute[i].to,
                    cvxAmount,
                    cvxIntermed[i]
                );
            }
        }
    }

    ///
    /// @dev converts all to deposit ccy to prepare for investment logic after going out from eme mode
    ///
    function beforeEmeMode(
        CurveConvexBase.BasePoolMetaStorage storage $$$,
        CurveConvexBase.BasePoolStorage storage $$,
        CurveConvexBase.BaseConstantsStorage storage $,
        address depositCcy
    ) external {
        // if emergency pool is disabled no swaps
        if ($.EME_POOL_DISABLED) {
            return;
        }

        // convert emergency currency to deposit currency
        uint256 amountToExchange = IERC20($.EMERGENCY_CCY).balanceOf(
            address(this)
        );

        if (amountToExchange == 0) return;

        ICurveConvexPeriphery periphery = ICurveConvexStrategy(address(this))
            .PERIPHERY();
        uint256 minOut = periphery.getExchangeAmount(
            $$._emergencyPool,
            $.EMERGENCY_CCY,
            depositCcy,
            amountToExchange
        );

        if (minOut == 0) {
            revert FijaEmeModeInvalidQuote();
        }

        minOut =
            (minOut *
                (CurveConvexConstants.BASIS_POINTS_DIVISOR - $.SLIPPAGE_SWAP)) /
            CurveConvexConstants.BASIS_POINTS_DIVISOR;

        CurveConvexExchangeLib._exchange(
            $$$,
            $$._emergencyPool,
            $.EMERGENCY_CCY,
            depositCcy,
            amountToExchange,
            minOut
        );
    }

    ///
    /// @dev converts all de-invested assets to emergency ccy
    ///
    function afterEmeMode(
        CurveConvexBase.BasePoolMetaStorage storage $$$,
        CurveConvexBase.BasePoolStorage storage $$,
        CurveConvexBase.BaseConstantsStorage storage $,
        address depositCcy
    ) external {
        // if emergency pool is disabled no swaps
        if ($.EME_POOL_DISABLED) {
            return;
        }
        // convert all deposit currency to emergency currency
        uint256 amountToExchange;
        if (depositCcy == CurveConvexConstants.ETH) {
            amountToExchange = address(this).balance;
        } else {
            amountToExchange = IERC20(depositCcy).balanceOf(address(this));
        }

        if (amountToExchange == 0) return;

        ICurveConvexPeriphery periphery = ICurveConvexStrategy(address(this))
            .PERIPHERY();
        uint256 minOut = periphery.getExchangeAmount(
            $$._emergencyPool,
            depositCcy,
            $.EMERGENCY_CCY,
            amountToExchange
        );

        if (minOut == 0) {
            revert FijaEmeModeInvalidQuote();
        }

        minOut =
            (minOut *
                (CurveConvexConstants.BASIS_POINTS_DIVISOR -
                    $.SLIPPAGE_EMERGENCY)) /
            CurveConvexConstants.BASIS_POINTS_DIVISOR;

        CurveConvexExchangeLib._exchange(
            $$$,
            $$._emergencyPool,
            depositCcy,
            $.EMERGENCY_CCY,
            amountToExchange,
            minOut
        );
    }
}

